import {SurfaceScene} from './scene.js';
const $=id=>document.getElementById(id),videos=[$('videoA'),$('videoB')],scene=new SurfaceScene($('scene')),worker=new Worker('scan-worker.js');
let serial=0,busy=false,running=false,last=null,calibration=null,backgroundReady=false;const pending=new Map(),logs=[],files=[null,null],captureCanvases=[document.createElement('canvas'),document.createElement('canvas')];
function log(s){logs.push(`${new Date().toISOString()} ${s}`);$('log').textContent=logs.slice(-120).join('\n');}
worker.onmessage=e=>{const p=pending.get(e.data.id);if(!p)return;pending.delete(e.data.id);if(e.data.error)p.reject(Error(e.data.error));else p.resolve(e.data.result)};worker.onerror=e=>{for(const p of pending.values())p.reject(Error(e.message));pending.clear();$('runtime').textContent='処理エラー';};
const call=(type,data={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});worker.postMessage({id,type,...data});});
const opts=()=>({size:+$('size').value,step:+$('step').value,ncc:+$('ncc').value,unique:+$('unique').value,near:+$('near').value,far:+$('far').value,ruler:+$('ruler').value,refs:[+$('refA').value,+$('refB').value]});
function status(s){$('runtime').textContent=s;log(s);}
async function guarded(fn){if(busy)throw Error('処理中です');busy=true;document.querySelectorAll('#calibrate,#background,#scan').forEach(b=>b.disabled=true);try{return await fn();}catch(e){status(e.message);$('metrics').textContent=e.message;throw e;}finally{busy=false;document.querySelectorAll('#calibrate,#background,#scan').forEach(b=>b.disabled=false);}}
function validVideos(){if(videos.some(v=>!v.videoWidth))throw Error('動画を2本選択してください');}
const bounds=()=>({min:Math.max(0,-+$('offset').value),max:Math.min(videos[0].duration,videos[1].duration-+$('offset').value)});
async function seekOne(v,t){if(t<0||t>v.duration)throw Error(`動画時刻${t.toFixed(3)}秒が範囲外です`);v.pause();if(Math.abs(v.currentTime-t)<.0005&&v.readyState>=2)return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(Error('動画のシークが完了しません'))},15000);const cleanup=()=>{clearTimeout(timer);v.removeEventListener('seeked',done);v.removeEventListener('error',fail)};const done=()=>{cleanup();resolve()};const fail=()=>{cleanup();reject(Error('動画をデコードできません'))};v.addEventListener('seeked',done);v.addEventListener('error',fail);v.currentTime=t;});}
function capture(i,maxEdge=960){const v=videos[i],rot=+$('rot'+(i?'B':'A')).value,swap=rot%180!==0,W=swap?v.videoHeight:v.videoWidth,H=swap?v.videoWidth:v.videoHeight,s=Math.min(1,maxEdge/Math.max(W,H)),c=captureCanvases[i];c.width=Math.round(W*s);c.height=Math.round(H*s);const ctx=c.getContext('2d',{willReadFrequently:true});ctx.translate(c.width/2,c.height/2);ctx.rotate(rot*Math.PI/180);ctx.drawImage(v,-v.videoWidth*s/2,-v.videoHeight*s/2,v.videoWidth*s,v.videoHeight*s);ctx.setTransform(1,0,0,1,0,0);return ctx.getImageData(0,0,c.width,c.height);}
function drawImage(id,im){const c=$(id);c.width=im.width;c.height=im.height;c.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(im.data),im.width,im.height),0,0);}
function drawInputs(){for(let i=0;i<2;i++)if(videos[i].videoWidth)drawImage(i?'viewB':'viewA',capture(i));$('times').textContent=`A ${videos[0].currentTime.toFixed(3)}s / B ${videos[1].currentTime.toFixed(3)}s`;}
async function seek(t){validVideos();const b=bounds();t=Math.min(b.max,Math.max(b.min,t));await Promise.all([seekOne(videos[0],t),seekOne(videos[1],t+(+$('offset').value))]);$('time').value=t.toFixed(3);$('timeline').min=b.min;$('timeline').max=b.max;$('timeline').value=t;drawInputs();return t;}
async function loadFile(i,file){if(!file)return;if(files[i]?.url)URL.revokeObjectURL(files[i].url);files[i]={file,url:URL.createObjectURL(file)};const v=videos[i];v.src=files[i].url;await new Promise((resolve,reject)=>{v.onloadeddata=resolve;v.onerror=()=>reject(Error('動画を読み込めません'));v.load();});$('name'+(i?'B':'A')).textContent=`${file.name} · ${v.videoWidth}×${v.videoHeight}`;calibration=null;backgroundReady=false;last=null;scene.setPoints(new Float32Array(),new Uint8Array());$('calibrationInfo').textContent='入力変更：校正と背景を取り直してください';drawInputs();if(videos.every(v=>v.videoWidth)){await seek(bounds().min);$('bgA').value=bounds().min;$('bgB').value=bounds().min+(+$('offset').value);}status('動画を読み込みました');}
function showCalibration(c){calibration=c;backgroundReady=false;scene.setCameras(c.cameras);$('baseline').textContent=c.baseline.toFixed(3)+' m';$('calibrationInfo').textContent=c.cameras.map((x,i)=>`${i?'B':'A'}: RMS ${x.rms?.toFixed(2)??'?'}px / 画角 ${x.fov?.toFixed(1)??'?'}° / 基準紙 ${x.reference??'JSON'}`).join('\n');}
async function calibrate(){return guarded(async()=>{validVideos();status('A4からカメラの位置を推定中');const c=await call('calibrate',{images:[capture(0,1920),capture(1,1920)],opts:opts()});showCalibration(c);status('校正を取得しました。背景を学習してください');return c;});}
async function background(){return guarded(async()=>{validVideos();if(!calibration)throw Error('先にカメラを校正してください');status('影判定用の背景を学習中');const t=videos[0].currentTime;await Promise.all([seekOne(videos[0],+$('bgA').value),seekOne(videos[1],+$('bgB').value)]);const images=[capture(0),capture(1)];const r=await call('background',{images,opts:opts()});backgroundReady=true;r.previews.forEach((im,i)=>drawImage(i?'rectB':'rectA',im));await seek(t);status('背景学習完了。前景を吸収しないよう背景を固定しました');return {backgroundReady:true};});}
async function scan(){return guarded(async()=>{validVideos();if(!calibration||!backgroundReady)throw Error('校正と背景学習が必要です');status('エピポーラ線上を照合中');const t=videos[0].currentTime;const r=await call('scan',{images:[capture(0),capture(1)],opts:opts()});last={...r,timeA:t,timeB:videos[1].currentTime,offset:+$('offset').value,options:opts(),files:files.map(f=>f?.file.name)};r.previews.forEach((im,i)=>drawImage(i?'rectB':'rectA',im));scene.setPoints(r.points,r.colors);$('pointCount').textContent=(r.points.length/3).toLocaleString();$('coverage').textContent=(r.coverage*100).toFixed(1)+' %';$('latency').textContent=r.ms.toFixed(0)+' ms';$('metrics').textContent=`前景 A ${r.foreground[0].pixels}px / B ${r.foreground[1].pixels}px、影除外 ${r.foreground.map(f=>f.shadow).join(' / ')}px\n棄却：模様不足 ${r.counts.texture} / 相関不足 ${r.counts.correlation} / 曖昧 ${r.counts.ambiguous} / 往復不一致 ${r.counts.roundtrip} / 孤立 ${r.counts.neighborhood} / 幾何 ${r.counts.geometry}`;$('verdict').innerHTML=(r.points.length?'観測点あり':'復元失敗')+'<span>表面の成立は原画像・3Dで判定</span>';status(`スキャン完了：${r.points.length/3}点、${r.ms.toFixed(0)}ms`);return summary();});}
function summary(){if(!last)return null;const {points,colors,uv,previews,accepted,...r}=last;return {...r,pointCount:points.length/3};}
async function sequence(){running=!running;$('run').textContent=running?'連続スキャンを停止':'連続スキャンを開始';while(running){try{await scan();if(!running)break;const t=videos[0].currentTime+.1;if(t>bounds().max){running=false;break;}await seek(t);}catch(e){running=false;break;}await new Promise(r=>setTimeout(r,0));}$('run').textContent='連続スキャンを開始';}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function exportJSON(){if(!last)return;download('surface-result.json',JSON.stringify({...summary(),calibration,points:Array.from(last.points),colors:Array.from(last.colors),correspondences:Array.from(last.uv)},null,2),'application/json');}
function exportPLY(){if(!last)return;const n=last.points.length/3,lines=['ply','format ascii 1.0','comment Epipolar observed surface; units meters',`element vertex ${n}`,'property float x','property float y','property float z','property uchar red','property uchar green','property uchar blue','end_header'];for(let i=0;i<n;i++)lines.push([...last.points.slice(i*3,i*3+3),...last.colors.slice(i*3,i*3+3)].join(' '));download('surface.ply',lines.join('\n'),'text/plain');}
function ui(fn){return ()=>Promise.resolve().then(fn).catch(e=>log(e.message));}
['A','B'].forEach((s,i)=>$('file'+s).addEventListener('change',ui(()=>loadFile(i,$('file'+s).files[0]))));$('calibrate').onclick=ui(calibrate);$('background').onclick=ui(background);$('scan').onclick=ui(scan);$('run').onclick=ui(sequence);$('seek').onclick=ui(()=>seek(+$('time').value));$('timeline').onchange=ui(()=>seek(+$('timeline').value));$('back').onclick=ui(()=>seek(videos[0].currentTime-1));$('forward').onclick=ui(()=>seek(videos[0].currentTime+1));$('exportJSON').onclick=exportJSON;$('exportPLY').onclick=exportPLY;['front','oblique','top'].forEach(v=>$(v).onclick=()=>scene.view(v));
$('calibrationFile').onchange=ui(async()=>{const value=JSON.parse(await $('calibrationFile').files[0].text());showCalibration(await call('import',{value}));status('校正JSONを読み込みました');});
for(const id of ['rotA','rotB','ruler','refA','refB'])$(id).onchange=()=>{calibration=null;backgroundReady=false;drawInputs();$('calibrationInfo').textContent='設定変更：校正・背景を取り直してください'};
$('size').onchange=()=>{backgroundReady=false;status('解像度変更：背景を学習し直してください')};$('offset').onchange=ui(()=>seek(videos[0].currentTime));
$('rectA').onclick=e=>{if(!last)return;const c=e.currentTarget,b=c.getBoundingClientRect(),y=(e.clientY-b.top)*c.height/b.height;for(const id of ['rectA','rectB']){drawImage(id,last.previews[id==='rectA'?0:1]);const ctx=$(id).getContext('2d');ctx.strokeStyle='#ffc34e';ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(c.width,y);ctx.stroke();}};
window.SurfaceScan={seek,calibrate,background,scan,summary,detect:async()=>call('detect',{images:[capture(0,1920),capture(1,1920)]}),get calibration(){return calibration},get last(){return last},get ready(){return !busy},setOptions(values){for(const [k,v]of Object.entries(values)){if($(k))$(k).value=v;}},view:v=>scene.view(v),logs};
call('init').then(info=>{status('準備完了');log(JSON.stringify(info));window.SurfaceScan.cvInfo=info;}).catch(e=>status(e.message));
